#include "genesis/cognition/continuity.hpp"
#include "genesis/cognition/continuity_persistence.hpp"
#include <chrono>
#include <iostream>
#include <string>
int main(){using namespace genesis;LineageIdentity identity;identity.organism_id="benchmark";identity.genesis_id="genesis";identity.lineage_id="lineage";identity.birth_event_id="birth";cognition::AutobiographicalContinuity journal(identity,{},10000,100);const auto start=std::chrono::steady_clock::now();for(std::size_t i=0;i<10000;++i){const auto n=std::to_string(i);memory::MemoryNode m{"memory-"+n,"benchmark",std::string(64,'a'),std::string(64,'b'),"benchmark",memory::MemoryKind::episode,memory::Origin::direct_experience,memory::IdentityScope::organism_private,memory::ActivationState::available,.8,.8,0,i,i,0,{"event"}};if(!journal.append("event-"+n,m,i+1,i))return 1;if(i%100==99&&!journal.checkpoint("checkpoint-"+n,i))return 2;}const auto built=std::chrono::steady_clock::now();const auto bytes=cognition::ContinuityStore::serialize(journal);const auto restored=cognition::ContinuityStore::deserialize(bytes);const auto end=std::chrono::steady_clock::now();if(!journal.verify()||!restored||restored->events().size()!=10000)return 3;std::cout<<"events="<<journal.events().size()<<" checkpoints="<<journal.checkpoints().size()<<" build_seconds="<<std::chrono::duration<double>(built-start).count()<<" snapshot_bytes="<<bytes.size()<<" roundtrip_seconds="<<std::chrono::duration<double>(end-built).count()<<'\n';}
